breach.segment:
// Ignore pods that stopped reporting (deleted) more than 5 minutes before their cluster's newest sample
WHERE last_seen >= cluster_newest - 5 minutes
// Failed pods persist until garbage collection and Succeeded is normal for Jobs, so only Pending and Unknown alert.
// Threshold: minutes stuck. Keep it at least 15 minutes below the rule's lookback, because data arrives
// several minutes late.
| WHERE phase IN ("Pending", "Unknown") AND stuck_minutes >= 10
| KEEP resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster,
       resource.attributes.namespace, attributes.pod, phase, stuck_minutes, last_seen
| SORT stuck_minutes DESC
